import { Parser, ReplacementRules, popKeys } from './parser';
import { Generators, createPromptInfo, createSampler, createModel, PromptInfo } from '../data';
import { ParserError } from '../exceptions';
import { readJsonObject, take, promptList } from './helpers';

const SAMPLER_PARAMS = ['Seed', 'Steps', 'CfgScale'];
const REPLACEMENT_RULES: ReplacementRules = [['CfgScale', 'cfg_scale']];

/**
 * Parser for images generated by Stability Matrix's inference UI, which writes a
 * `parameters-json` chunk next to AUTOMATIC1111 parameters and a ComfyUI node graph
 */
export class StabilityMatrixParser extends Parser {
  public readonly generator = Generators.STABILITY_MATRIX;

  async parse(parameters: Record<string, any>): Promise<PromptInfo> {
    if (parameters['parameters-json'] === undefined) {
      throw new ParserError('no parameters-json found');
    }
    const params = readJsonObject(parameters['parameters-json'], 'parameters-json');

    const samplerName = take(params, 'Sampler') ?? 'unknown';
    const prompt = take(params, 'PositivePrompt');
    const negativePrompt = take(params, 'NegativePrompt');
    const name = take(params, 'ModelName');
    const hash = take(params, 'ModelHash');
    const model = name || hash ? createModel({ name: name ?? undefined, hash: hash ?? undefined }) : undefined;

    const sampler = createSampler(samplerName, this.normalizeParameters(popKeys(SAMPLER_PARAMS, params), REPLACEMENT_RULES), {
      model,
      prompts: promptList(prompt),
      negativePrompts: promptList(negativePrompt),
    });

    // drop the video settings that are written with default values for every image
    const metadata = Object.fromEntries(Object.entries(params).filter(([, value]) => value !== null && value !== 0 && value !== false));
    return createPromptInfo(this.generator, [sampler], metadata, parameters);
  }
}
